/**
 * tests/bill-stamp.test.mjs
 * -------------------------
 * The /issues "Last Updated" card is generated by scripts/build-bill-stamp.mjs.
 * These checks fail `npm test` when tracker content changed without
 * `npm run bills:stamp`, or when the HTML card drifts from LAST_UPDATED.
 */

import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { test } from 'node:test';
import { formatStamp } from '../scripts/build-bill-stamp.mjs';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');

test('Last Updated stamp matches the bill tracker (run npm run bills:stamp)', () => {
  execFileSync(process.execPath, [join(ROOT, 'scripts/build-bill-stamp.mjs'), '--check'], {
    cwd: ROOT,
    stdio: 'pipe',
  });
});

test('stamp is formatted in Eastern time with the right zone label', () => {
  assert.deepEqual(formatStamp(new Date('2026-11-13T23:30:00Z')), { date: '11/13/26', time: '6:30 PM EST' });
  assert.deepEqual(formatStamp(new Date('2026-07-04T13:05:00Z')), { date: '07/04/26', time: '9:05 AM EDT' });
});
